// Education mode's question bank (plan 21), NO Phaser/DOM. The source of truth
// for the cards since 2026-11-12 (converted from the draft bank of 2026-11-11,
// now .claude/plans/Archive/).
//
// Card: { id, deck, q, answer, wrong: [w1, w2], explain, refs, retired?, zh }
//   id       permanent ('ST-01'): scheduler state, audits and logged answers key
//            on it, so a card is never renumbered or reused; a wrong card is
//            retired, not deleted
//   deck     a LEVELS key (the gut segment whose level introduces it), 'general', or 'super' (plan 34:
//            the challenge questions, harder than level 7 and any topic, offered only by the challenge
//            question bubble; once met they come back like any due card)
//   q        the question; answer the right option; wrong the two wrong ones
//            (common misconceptions where possible; shuffled at display time)
//   explain  shown after the answer: one or two sentences, at most 30 words
//   refs     REFERENCES numbers the card rests on
//   retired  true: never shown again (the id stays, so old answers still resolve)
//   zh       { q, answer, wrong, explain } in zh-Hans: every live card has one (plan 28,
//            tests/questions.test.js; terms in TRANSLATION_NOTES.md's card glossary); left
//            out of the audit hash, so a Chinese edit never makes an audit stale
//
// Facts are unaudited until src/questionAudits.js holds an audit whose hash
// matches the card (tools/audit_questions.mjs marks them). Writing rules: one
// fact per card, answerable in under 10 s on a phone; how the gut and its
// microbes work, never the player's own health, diet or habits, and no health or
// treatment advice; numbers only where the options differ by at least 10x.
//
// The general deck (cards about the microbiome as a whole, mixed into every
// level) is provisional: ST-10, JE-06, JE-08, JE-09, CO-02, RE-09 and IL-10,
// awaiting Michael's confirmation. Moving a card between decks keeps its audit.

import { LEVELS } from './config.js';

/** The level decks, in level order: the gut segments (a level break offers its own deck's new cards). */
export const LEVEL_DECKS = LEVELS.map((l) => l.key);

/** The decks: the level decks, then the general deck, then the challenge questions (plan 34). */
export const DECKS = [...LEVEL_DECKS, 'general', 'super'];

/** Every card, live and retired, in bank order (deck by deck). */
export const CARDS = [
  // ST: level 1, the stomach
  { id: 'ST-01', deck: 'stomach', q: 'Why do so few microbes live in the stomach?', answer: 'It is strongly acidic', wrong: ['It is too cold', 'No food reaches it'], explain: "Stomach acid kills most microbes we swallow, so it is the gut's first barrier.", refs: [1], zh: { q: '为什么胃里住的微生物这么少？', answer: '胃里酸性很强', wrong: ['胃里太冷', '食物到不了胃'], explain: '胃酸能杀死我们吞下的大多数微生物，所以胃是消化道的第一道屏障。' } },
  { id: 'ST-02', deck: 'stomach', q: "How acidic is the stomach's juice?", answer: 'Around pH 2, like lemon juice', wrong: ['About pH 7, like water', 'About pH 10, like soapy water'], explain: 'Gastric juice usually sits between pH 1.5 and 3.5, acidic enough to kill most bacteria.', refs: [1], zh: { q: '胃液有多酸？', answer: '约 pH 2，和柠檬汁差不多', wrong: ['约 pH 7，和水差不多', '约 pH 10，和肥皂水差不多'], explain: '胃液通常在 pH 1.5 到 3.5 之间，酸到足以杀死大多数细菌。' } },
  { id: 'ST-03', deck: 'stomach', q: 'Which bacterium lives in the stomachs of about half the people on Earth?', answer: 'Helicobacter pylori', wrong: ['Clostridioides difficile', 'Vibrio cholerae'], explain: "H. pylori infects roughly half the world's population; most carriers never notice it.", refs: [3], zh: { q: '地球上大约一半的人胃里都住着哪种细菌？', answer: '幽门螺杆菌', wrong: ['艰难梭菌', '霍乱弧菌'], explain: '世界上大约一半的人感染了幽门螺杆菌，大多数携带者从来没有察觉。' } },
  { id: 'ST-04', deck: 'stomach', q: 'How does H. pylori survive stomach acid?', answer: 'It makes ammonia to neutralise the acid around it', wrong: ['It builds a hard shell like a seed', "It hides inside our stomach cells' nuclei"], explain: 'Its enzyme urease turns urea into ammonia, creating a less acidic bubble around the bacterium.', refs: [4], zh: { q: '幽门螺杆菌怎样在胃酸里活下来？', answer: '它制造氨，中和身边的酸', wrong: ['它像种子一样长出硬壳', '它躲进胃细胞的细胞核里'], explain: '它的脲酶把尿素变成氨，在细菌周围形成一个酸性较弱的微环境。' } },
  { id: 'ST-05', deck: 'stomach', q: 'How did Barry Marshall show that H. pylori inflames the stomach?', answer: 'He drank a culture of it', wrong: ['He studied it only in mice', 'He took antibiotics for a year'], explain: 'In 1984 he swallowed the bacteria and developed gastritis. He later shared the 2005 Nobel Prize for this work.', refs: [5], zh: { q: '巴里·马歇尔怎样证明幽门螺杆菌会让胃发炎？', answer: '他喝下了它的培养液', wrong: ['他只在小鼠身上做研究', '他吃了一年抗生素'], explain: '1984 年他吞下这种细菌，得了胃炎。他后来因对幽门螺杆菌的研究，分享了 2005 年的诺贝尔奖。' } },
  { id: 'ST-06', deck: 'stomach', q: 'Where do most microbes found in the stomach come from?', answer: 'They are swallowed from the mouth', wrong: ['They travel up from the colon', 'They grow out of the stomach wall'], explain: 'We swallow saliva all day, and many oral bacteria are found further down the gut too.', refs: [6], zh: { q: '胃里发现的微生物大多从哪里来？', answer: '从嘴里吞下去的', wrong: ['从结肠往上跑来的', '从胃壁里长出来的'], explain: '我们整天都在吞口水，许多口腔细菌在肠道更深处也能找到。' } },
  { id: 'ST-07', deck: 'stomach', q: 'Is a healthy stomach sterile?', answer: 'No, it has a small community of microbes', wrong: ['Yes, completely', "It holds most of the gut's microbes"], explain: 'DNA surveys found a diverse but sparse community in the human stomach.', refs: [7], zh: { q: '健康的胃是无菌的吗？', answer: '不是，里面有一小群微生物', wrong: ['是的，完全无菌', '肠道的大部分微生物都在胃里'], explain: 'DNA 调查发现，人的胃里有一个种类多样但数量稀少的微生物群落。' } },
  { id: 'ST-08', deck: 'stomach', q: 'Medicines that lower stomach acid tend to let more of which microbes reach the intestine?', answer: 'Mouth bacteria', wrong: ['Skin bacteria', 'Soil bacteria'], explain: 'With less acid, more swallowed oral bacteria survive; people taking these drugs show more mouth-type bacteria in stool.', refs: [8], zh: { q: '降低胃酸的药物，往往会让哪类微生物更多地到达肠道？', answer: '口腔细菌', wrong: ['皮肤细菌', '土壤细菌'], explain: '胃酸少了，吞下的口腔细菌活下来的更多；服用这类药的人，粪便里口腔型细菌更多。' } },
  { id: 'ST-09', deck: 'stomach', q: 'About how many microbes are in each millilitre of stomach contents?', answer: 'About 10 to 1,000', wrong: ['About a million million', 'About a billion billion'], explain: 'The stomach holds tiny numbers compared with the colon, which carries around 100 billion per gram.', refs: [2], zh: { q: '每毫升胃内容物里大约有多少微生物？', answer: '约 10 到 1000 个', wrong: ['约一万亿个', '约一百亿亿个'], explain: '和结肠相比，胃里的数量少得可怜；结肠每克约有 1000 亿个。' } },
  { id: 'ST-10', deck: 'general', q: 'What does "gut microbiome" mean?', answer: 'The community of microbes living in the gut, and their genes', wrong: ['Only the microbes that cause disease', 'One species of helpful bacteria'], explain: 'It includes bacteria, archaea, fungi and viruses, most of them harmless.', refs: [9], zh: { q: '“肠道微生物组”是什么意思？', answer: '生活在肠道里的微生物群落及其基因', wrong: ['只指致病的微生物', '一种有益的细菌'], explain: '它包括细菌、古菌、真菌和病毒，其中大多数无害。' } },
  // DU: level 2, the duodenum
  { id: 'DU-01', deck: 'duodenum', q: 'Which digestive fluid poured into the duodenum makes life hard for bacteria?', answer: 'Bile', wrong: ['Saliva', 'Tears'], explain: 'Bile from the liver helps digest fat and is also toxic to many bacteria.', refs: [10], zh: { q: '流入十二指肠的哪种消化液让细菌很难生存？', answer: '胆汁', wrong: ['唾液', '眼泪'], explain: '来自肝脏的胆汁帮助消化脂肪，对许多细菌也有毒。' } },
  { id: 'DU-02', deck: 'duodenum', q: 'How does bile harm bacteria?', answer: 'It acts like a detergent and damages their membranes', wrong: ['It freezes them', 'It blocks their access to light'], explain: 'Bile acids dissolve fats, including the fatty membranes around bacterial cells.', refs: [10], zh: { q: '胆汁怎样伤害细菌？', answer: '它像洗涤剂一样破坏细菌的膜', wrong: ['它把细菌冻住', '它让细菌见不到光'], explain: '胆汁酸能溶解脂肪，包括细菌细胞外面那层脂质膜。' } },
  { id: 'DU-03', deck: 'duodenum', q: 'Many gut bacteria resist bile with an enzyme called what?', answer: 'Bile salt hydrolase', wrong: ['Amylase', 'Lactase'], explain: 'Bile salt hydrolase changes bile acids into forms that are less harmful to the bacterium.', refs: [10], zh: { q: '许多肠道细菌靠一种叫什么的酶来抵抗胆汁？', answer: '胆盐水解酶', wrong: ['淀粉酶', '乳糖酶'], explain: '胆盐水解酶把胆汁酸变成对细菌伤害较小的形式。' } },
  { id: 'DU-04', deck: 'duodenum', q: 'Compared with the colon, how many microbes does the duodenum hold?', answer: 'Far fewer', wrong: ['About the same', 'Far more'], explain: 'Acid and bile keep duodenal numbers low, roughly 1,000 per millilitre against about 100 billion in the colon.', refs: [11], zh: { q: '和结肠相比，十二指肠里的微生物有多少？', answer: '少得多', wrong: ['差不多', '多得多'], explain: '胃酸和胆汁让十二指肠里的数量很低，每毫升约 1000 个，而结肠约有 1000 亿个。' } },
  { id: 'DU-05', deck: 'duodenum', q: 'A landmark 2013 trial delivered donor stool into the duodenum. Which infection did it treat?', answer: 'Recurrent C. difficile infection', wrong: ['The common cold', 'H. pylori infection'], explain: 'Stool transplants cured recurrent C. difficile far more often than antibiotics alone in that trial.', refs: [12], zh: { q: '2013 年一项里程碑式的试验把供体粪便送进十二指肠。它治疗的是哪种感染？', answer: '复发性艰难梭菌感染', wrong: ['普通感冒', '幽门螺杆菌感染'], explain: '在那项试验中，粪菌移植治愈复发性艰难梭菌感染的比例远高于单用抗生素。' } },
  { id: 'DU-06', deck: 'duodenum', q: 'What is a fecal microbiota transplant?', answer: "Moving gut microbes from a healthy donor's stool into a patient", wrong: ['Transplanting a piece of intestine', 'A pill containing one bacterial species'], explain: 'It replaces a disrupted community with a whole donor community, not a single strain.', refs: [12], zh: { q: '什么是粪菌移植？', answer: '把健康供体粪便里的肠道微生物移入病人体内', wrong: ['移植一段肠子', '只含一种细菌的药丸'], explain: '它用供体的整个微生物群落取代被打乱的群落，而不是只补充单一菌株。' } },
  { id: 'DU-07', deck: 'duodenum', q: 'How common are fungi in the gut compared with bacteria?', answer: 'Much rarer', wrong: ['Much more common', 'About equal'], explain: 'Fungi make up a small share of gut microbes; common ones include Saccharomyces and Candida.', refs: [13], zh: { q: '和细菌相比，肠道里的真菌有多常见？', answer: '少得多', wrong: ['多得多', '差不多一样多'], explain: '真菌只占肠道微生物的一小部分，常见的有酵母属（Saccharomyces）和念珠菌属（Candida）。' } },
  { id: 'DU-08', deck: 'duodenum', q: 'Bacteria common in the upper small intestine, such as Streptococcus, are also common where?', answer: 'In the mouth', wrong: ['On the skin', 'In the soil'], explain: "Upper small-intestine communities resemble oral ones more than the colon's.", refs: [14], zh: { q: '小肠上段常见的细菌（如链球菌）在哪里也很常见？', answer: '嘴里', wrong: ['皮肤上', '土壤里'], explain: '小肠上段的菌群更像口腔菌群，而不像结肠的菌群。' } },
  { id: 'DU-09', deck: 'duodenum', q: 'Most bacteria in the upper small intestine can do what?', answer: 'Survive with or without oxygen', wrong: ['Survive only without oxygen', 'Make food from sunlight'], explain: 'Some oxygen reaches the upper gut, so oxygen-tolerant bacteria do well there.', refs: [2], zh: { q: '小肠上段的大多数细菌有什么特点？', answer: '有没有氧气都能生存', wrong: ['只能在无氧环境中生存', '利用阳光制造食物'], explain: '有些氧气能到达肠道上段，所以能在有氧环境中生存的细菌在那里活得很好。' } },
  { id: 'DU-10', deck: 'duodenum', q: 'Why do we know less about small-intestine microbes than about stool microbes?', answer: 'The small intestine is hard to sample', wrong: ['It has no microbes', 'Its microbes cannot be identified'], explain: 'Sampling needs a tube, a capsule or surgery, while stool is easy to collect.', refs: [14], zh: { q: '为什么我们对小肠微生物的了解比粪便微生物少？', answer: '小肠很难取样', wrong: ['小肠里没有微生物', '小肠里的微生物无法鉴定'], explain: '取样需要插管、胶囊或手术，而粪便很容易收集。' } },
  // JE: level 3, the jejunum
  { id: 'JE-01', deck: 'jejunum', q: 'Besides acid and bile, what keeps microbe numbers low in the small intestine?', answer: 'Contents move through quickly', wrong: ['It gets no food', 'It is exposed to light'], explain: 'Fast flow washes microbes onward before they can build up large populations.', refs: [14], zh: { q: '除了胃酸和胆汁，还有什么让小肠里的微生物数量保持很低？', answer: '内容物流过得很快', wrong: ['小肠得不到食物', '小肠暴露在光线下'], explain: '快速的流动把微生物冲往下游，它们来不及大量繁殖。' } },
  { id: 'JE-02', deck: 'jejunum', q: 'Small-intestine microbes compete with whom for simple sugars?', answer: 'You, the host', wrong: ['Viruses only', 'Nobody; sugars go untouched'], explain: 'Both we and our microbes absorb simple sugars here, so microbes that grab them fast do well.', refs: [15], zh: { q: '小肠里的微生物和谁争夺单糖？', answer: '你，也就是宿主', wrong: ['只和病毒争', '没人争，单糖没人动'], explain: '我们和我们的微生物都在这里吸收单糖，所以抢得快的微生物活得好。' } },
  { id: 'JE-03', deck: 'jejunum', q: 'Without enough lactase, where does undigested milk sugar end up?', answer: 'In the colon, where bacteria ferment it', wrong: ['It stays in the stomach', 'It is absorbed anyway'], explain: 'Colon bacteria ferment leftover lactose, and the gas they make causes the bloating of lactose intolerance.', refs: [16], zh: { q: '如果乳糖酶不够，没消化的乳糖最后去了哪里？', answer: '进入结肠，被细菌发酵', wrong: ['留在胃里', '照样被吸收'], explain: '结肠细菌发酵剩下的乳糖，产生的气体造成乳糖不耐受时的腹胀。' } },
  { id: 'JE-04', deck: 'jejunum', q: "How does mucus in the small intestine differ from the colon's?", answer: 'It is a single, looser layer', wrong: ['There is no mucus there', 'It is thicker, with two layers'], explain: 'The colon has a dense inner layer that keeps bacteria off the wall; the small intestine relies more on antimicrobial molecules.', refs: [17], zh: { q: '小肠的黏液和结肠的有什么不同？', answer: '只有一层，而且比较松散', wrong: ['那里根本没有黏液', '更厚，有两层'], explain: '结肠有一层致密的内层黏液，把细菌挡在肠壁之外；小肠更多依靠抗菌分子。' } },
  { id: 'JE-05', deck: 'jejunum', q: 'Travelling from the small intestine to the colon, oxygen levels do what?', answer: 'Fall', wrong: ['Rise', 'Stay the same'], explain: 'The colon is almost oxygen-free, which shapes which microbes can live there.', refs: [2], zh: { q: '从小肠到结肠，氧气含量会怎样？', answer: '降低', wrong: ['升高', '不变'], explain: '结肠里几乎没有氧气，这决定了哪些微生物能在那里生活。' } },
  { id: 'JE-06', deck: 'general', q: 'How many genes does your gut microbiome carry compared with your own genome?', answer: 'About 150 times more', wrong: ['About the same', 'About 10 times fewer'], explain: 'A 2010 gene catalogue counted about 3.3 million microbial genes, against roughly 20,000 human genes.', refs: [18], zh: { q: '和你自己的基因组相比，你的肠道微生物组携带多少基因？', answer: '约多 150 倍', wrong: ['差不多一样多', '约只有 1/10'], explain: '2010 年的一份基因目录统计到约 330 万个微生物基因，而人类基因大约 2 万个。' } },
  { id: 'JE-07', deck: 'jejunum', q: 'Besides bacteria, which other kind of single-celled life lives in the human gut?', answer: 'Archaea', wrong: ['Plants', 'Algae'], explain: "Archaea such as Methanobrevibacter smithii live in many people's guts and make methane.", refs: [19], zh: { q: '除了细菌，还有哪一类单细胞生物生活在人的肠道里？', answer: '古菌', wrong: ['植物', '藻类'], explain: '史氏甲烷短杆菌等古菌生活在许多人的肠道里，会产生甲烷。' } },
  { id: 'JE-08', deck: 'general', q: 'Most viruses in the gut infect what?', answer: 'Bacteria', wrong: ['Human cells', 'Fungi'], explain: 'Gut viruses are mostly bacteriophages, which shape bacterial communities by infecting them.', refs: [20], zh: { q: '肠道里的大多数病毒感染的是什么？', answer: '细菌', wrong: ['人体细胞', '真菌'], explain: '肠道里的病毒大多是噬菌体，它们通过感染细菌来塑造细菌群落。' } },
  { id: 'JE-09', deck: 'general', q: 'Do most gut bacteria cause disease?', answer: 'No; most are harmless or helpful', wrong: ['Yes, almost all', 'About half do'], explain: 'Healthy people carry hundreds of bacterial species without getting sick.', refs: [9], zh: { q: '大多数肠道细菌会致病吗？', answer: '不会，大多无害甚至有益', wrong: ['会，几乎全部都会', '大约一半会'], explain: '健康的人身上带着几百种细菌，却不会生病。' } },
  { id: 'JE-10', deck: 'jejunum', q: 'Roughly how large is the inside surface of your whole digestive tract?', answer: 'About half a badminton court', wrong: ['About a tennis court', 'About a postcard'], explain: 'A 2014 study revised the old tennis-court estimate down to about 32 square metres, with villi and folds doing most of the work.', refs: [21], zh: { q: '你整个消化道的内表面大约有多大？', answer: '大约半个羽毛球场', wrong: ['大约一个网球场', '大约一张明信片'], explain: '2014 年的一项研究把过去“一个网球场”的估计下调到约 32 平方米，大部分面积来自绒毛和褶皱。' } },
  // IL: level 4, the ileum
  { id: 'IL-01', deck: 'ileum', q: 'What do Paneth cells in the small intestine release to control microbes?', answer: 'Antimicrobial peptides', wrong: ['Bile', 'Stomach acid'], explain: 'Paneth cells sit at the base of intestinal crypts and release small proteins that kill or block bacteria.', refs: [22], zh: { q: '小肠里的潘氏细胞释放什么来控制微生物？', answer: '抗菌肽', wrong: ['胆汁', '胃酸'], explain: '潘氏细胞位于肠隐窝底部，释放能杀死或阻挡细菌的小型蛋白质。' } },
  { id: 'IL-02', deck: 'ileum', q: 'What happens to most bile acids after they help digest fat?', answer: 'They are reabsorbed in the ileum and recycled', wrong: ['They leave the body in stool', 'They are destroyed in the stomach'], explain: 'About 95% of bile acids are taken back up at the end of the small intestine and returned to the liver.', refs: [23], zh: { q: '大多数胆汁酸帮助消化脂肪之后会怎样？', answer: '在回肠被重新吸收，循环利用', wrong: ['随粪便排出体外', '在胃里被分解'], explain: '约 95% 的胆汁酸在小肠末端被重新吸收，送回肝脏。' } },
  { id: 'IL-03', deck: 'ileum', q: 'Moving down the small intestine, microbe numbers do what?', answer: 'Rise steadily', wrong: ['Fall', 'Stay the same'], explain: 'Numbers climb from about 1,000 per millilitre near the stomach to tens of millions in the ileum.', refs: [2], zh: { q: '沿着小肠往下，微生物数量会怎样？', answer: '稳步增加', wrong: ['减少', '不变'], explain: '数量从靠近胃处的每毫升约 1000 个，增加到回肠里的几千万个。' } },
  { id: 'IL-04', deck: 'ileum', q: 'What helps stop colon bacteria from flowing back into the ileum?', answer: 'The ileocecal valve', wrong: ['The appendix', "The stomach's exit valve"], explain: 'This valve between the small and large intestine limits backflow from the dense colon community.', refs: [14], zh: { q: '什么帮助阻止结肠细菌倒流进回肠？', answer: '回盲瓣', wrong: ['阑尾', '胃的出口瓣膜'], explain: '这个位于小肠和大肠之间的瓣膜，限制了菌群密集的结肠内容物倒流。' } },
  { id: 'IL-05', deck: 'ileum', q: "How fast can the ileum's microbial community change?", answer: 'Within hours to days', wrong: ['It never changes', 'Only once a year'], explain: 'Studies of people with an ileostomy found ileal communities shift quickly over time.', refs: [24], zh: { q: '回肠的微生物群落变化有多快？', answer: '几小时到几天之内', wrong: ['从不变化', '一年才变一次'], explain: '对回肠造口者的研究发现，回肠菌群会随时间迅速变化。' } },
  { id: 'IL-06', deck: 'ileum', q: 'What are the clusters of immune tissue in the ileum that sample gut microbes called?', answer: "Peyer's patches", wrong: ['Villi', 'Taste buds'], explain: "Peyer's patches take up microbes and their molecules from the gut and show them to immune cells.", refs: [25], zh: { q: '回肠里那些采样肠道微生物的淋巴组织叫什么？', answer: '派尔集合淋巴结', wrong: ['绒毛', '味蕾'], explain: '派尔集合淋巴结从肠道摄取微生物及其分子，并把它们呈递给免疫细胞。' } },
  { id: 'IL-07', deck: 'ileum', q: 'Which antibody does the gut release in large amounts to coat microbes?', answer: 'IgA', wrong: ['IgE', 'Insulin'], explain: 'IgA is the most abundant antibody our bodies make; much of it coats gut bacteria without killing them.', refs: [26], zh: { q: '肠道大量释放哪种抗体来包裹微生物？', answer: 'IgA', wrong: ['IgE', '胰岛素'], explain: 'IgA 是我们体内产生最多的抗体；其中很多包裹着肠道细菌，却不杀死它们。' } },
  { id: 'IL-08', deck: 'ileum', q: 'How does a healthy immune system treat resident gut microbes?', answer: 'It keeps them in check without attacking them all', wrong: ['It tries to kill every one', 'It ignores them completely'], explain: 'The gut immune system tolerates resident microbes while keeping them away from the gut wall.', refs: [27], zh: { q: '健康的免疫系统怎样对待常驻的肠道微生物？', answer: '控制它们，而不是一味攻击', wrong: ['想要杀死每一个', '完全不理会'], explain: '肠道免疫系统容忍常驻微生物，同时让它们远离肠壁。' } },
  { id: 'IL-09', deck: 'ileum', q: 'Colon bacteria make vitamin B12, but we absorb B12 in the ileum. Why does colon-made B12 help us little?', answer: 'It is made downstream of where B12 is absorbed', wrong: ['Our bodies cannot use B12 at all', 'Bacteria eat all of it in the stomach'], explain: 'We rely on B12 from food; much bacterial B12 is made in the colon, past the ileum.', refs: [28], zh: { q: '结肠细菌会制造维生素 B12，但 B12 在回肠被吸收。为什么结肠造的 B12 对我们帮助不大？', answer: '它在吸收 B12 的位置下游才造出来', wrong: ['我们的身体根本不能利用 B12', '细菌在胃里把它全吃掉了'], explain: '我们靠食物获得 B12；细菌的 B12 很多是在结肠造的，已经过了回肠。' } },
  { id: 'IL-10', deck: 'general', q: 'Can gut microbes pass between people who live together?', answer: 'Yes, household members share strains', wrong: ['No, never', 'Only between identical twins'], explain: 'A 2023 study found people living together share many gut bacterial strains.', refs: [29], zh: { q: '肠道微生物能在住在一起的人之间传播吗？', answer: '能，同住的人会共享菌株', wrong: ['不能，从来不会', '只在同卵双胞胎之间'], explain: '2023 年的一项研究发现，住在一起的人共享许多肠道细菌菌株。' } },
  // CA: level 5, the caecum
  { id: 'CA-01', deck: 'caecum', q: 'What do gut bacteria make when they ferment fibre?', answer: 'Short-chain fatty acids', wrong: ['Sugar', 'Protein'], explain: 'Fermenting fibre produces short-chain fatty acids that our own cells absorb and use.', refs: [30], zh: { q: '肠道细菌发酵膳食纤维时会产生什么？', answer: '短链脂肪酸', wrong: ['糖', '蛋白质'], explain: '发酵纤维会产生短链脂肪酸，被我们自己的细胞吸收利用。' } },
  { id: 'CA-02', deck: 'caecum', q: 'Which of these is a short-chain fatty acid made by gut bacteria?', answer: 'Butyrate', wrong: ['Cholesterol', 'Glucose'], explain: 'The three main ones are acetate, propionate and butyrate.', refs: [30], zh: { q: '下面哪一种是肠道细菌产生的短链脂肪酸？', answer: '丁酸', wrong: ['胆固醇', '葡萄糖'], explain: '主要的三种是乙酸、丙酸和丁酸。' } },
  { id: 'CA-03', deck: 'caecum', q: 'One idea about the appendix is that it does what?', answer: 'Stores gut bacteria to restock the colon', wrong: ['Makes stomach acid', 'Digests bone'], explain: 'This is a hypothesis: the appendix may shelter a reserve of microbes after diarrhoea flushes the colon.', refs: [31], zh: { q: '关于阑尾，有一种说法认为它能做什么？', answer: '储存肠道细菌，用来补充结肠', wrong: ['制造胃酸', '消化骨头'], explain: '这只是一种假说：腹泻冲刷结肠之后，阑尾可能保存着一批后备微生物。' } },
  { id: 'CA-04', deck: 'caecum', q: 'Which animal relies on a huge caecum to ferment plants?', answer: 'Rabbit', wrong: ['Cat', 'Eagle'], explain: 'Hindgut fermenters such as rabbits and horses have a large caecum full of fibre-digesting microbes.', refs: [32], zh: { q: '哪种动物靠巨大的盲肠来发酵植物？', answer: '兔子', wrong: ['猫', '鹰'], explain: '兔子和马等后肠发酵动物，都有一个充满纤维消化微生物的大盲肠。' } },
  { id: 'CA-05', deck: 'caecum', q: 'Why do rabbits eat some of their own droppings?', answer: 'To absorb nutrients their caecum microbes made', wrong: ['To clean their burrow', 'Because they are thirsty'], explain: 'Soft caecal pellets carry vitamins and protein made by microbes, which the rabbit absorbs on a second pass.', refs: [32], zh: { q: '兔子为什么会吃一部分自己的粪便？', answer: '为了吸收盲肠微生物制造的营养', wrong: ['为了清洁洞穴', '因为口渴'], explain: '柔软的盲肠便里有微生物制造的维生素和蛋白质，兔子吃下后，营养第二次经过肠道时被吸收。' } },
  { id: 'CA-06', deck: 'caecum', q: 'In humans, what is the caecum?', answer: 'The start of the large intestine', wrong: ['Where food is first chewed', 'Where bile is made'], explain: 'Leftover food enters the caecum from the ileum, and large-scale fermentation begins.', refs: [2], zh: { q: '在人体中，盲肠是什么？', answer: '大肠的起点', wrong: ['食物最先被咀嚼的地方', '制造胆汁的地方'], explain: '剩下的食物从回肠进入盲肠，大规模的发酵从这里开始。' } },
  { id: 'CA-07', deck: 'caecum', q: 'Why can gut bacteria digest fibre when we cannot?', answer: 'They carry far more carbohydrate-digesting enzymes', wrong: ['Fibre melts in the colon', 'Our teeth break it down'], explain: 'Gut microbes encode thousands of enzymes for plant carbohydrates; our own genome has only a few dozen.', refs: [33], zh: { q: '为什么肠道细菌能消化纤维，而我们不能？', answer: '它们拥有多得多的碳水化合物消化酶', wrong: ['纤维在结肠里会融化', '我们的牙齿能把它磨碎'], explain: '肠道微生物编码数千种分解植物碳水化合物的酶，我们自己的基因组只有几十种。' } },
  { id: 'CA-08', deck: 'caecum', q: 'What is a prebiotic?', answer: 'Food that gut microbes selectively use, with a health benefit', wrong: ['A live bacterium', 'A medicine that kills bacteria'], explain: 'Certain fibres count as prebiotics because helpful gut microbes use them.', refs: [34], zh: { q: '什么是益生元？', answer: '能被肠道微生物选择性利用、对健康有益的食物成分', wrong: ['一种活细菌', '一种杀菌的药'], explain: '某些膳食纤维算作益生元，因为有益的肠道微生物会利用它们。' } },
  { id: 'CA-09', deck: 'caecum', q: 'What is a probiotic?', answer: 'Live microbes that give a health benefit in adequate amounts', wrong: ['Any food with fibre', 'A drug that kills bacteria'], explain: 'The definition requires a shown benefit; not every product with live microbes qualifies.', refs: [35], zh: { q: '什么是益生菌？', answer: '足量摄入时对健康有益的活微生物', wrong: ['任何含纤维的食物', '一种杀菌的药物'], explain: '定义要求有证据证明有益；并不是所有含活菌的产品都算。' } },
  { id: 'CA-10', deck: 'caecum', q: 'In mouse experiments, low-fibre diets over several generations led to what?', answer: 'Gut microbes were lost and did not return with fibre alone', wrong: ['Microbes became more diverse', 'Nothing changed'], explain: 'Species lost over generations came back only when the missing microbes were reintroduced.', refs: [36], zh: { q: '在小鼠实验中，连续几代吃低纤维饮食导致了什么？', answer: '部分肠道微生物消失，只补纤维也回不来', wrong: ['微生物变得更多样', '什么都没变'], explain: '几代之间失去的物种，只有重新引入缺失的微生物后才回来。' } },
  // CO: level 6, the colon
  { id: 'CO-01', deck: 'colon', q: 'Where in the gut do most microbes live?', answer: 'The colon', wrong: ['The stomach', 'The small intestine'], explain: 'The colon holds the vast majority of gut microbes, around 100 billion per millilitre of contents.', refs: [11], zh: { q: '肠道里的大多数微生物住在哪里？', answer: '结肠', wrong: ['胃', '小肠'], explain: '结肠容纳了绝大部分肠道微生物，每毫升内容物约有 1000 亿个。' } },
  { id: 'CO-02', deck: 'general', q: 'How does the number of bacterial cells in your body compare with your own cells?', answer: 'About equal', wrong: ['About 10 times more bacteria', 'About 100 times fewer bacteria'], explain: 'The popular 10-to-1 claim was revised in 2016 to roughly 38 trillion bacteria and 30 trillion human cells.', refs: [11], zh: { q: '你体内细菌细胞的数量和你自己的细胞相比如何？', answer: '大约一样多', wrong: ['细菌约多 10 倍', '细菌约少 100 倍'], explain: '流行的“10 比 1”说法在 2016 年被修正为约 38 万亿个细菌对 30 万亿个人体细胞。' } },
  { id: 'CO-03', deck: 'colon', q: 'What is the main fuel for the cells lining your colon?', answer: 'Butyrate made by gut bacteria', wrong: ['Glucose from the blood', 'Stomach acid'], explain: 'Colon lining cells get most of their energy from butyrate produced by fermenting bacteria.', refs: [37], zh: { q: '结肠内壁细胞的主要燃料是什么？', answer: '肠道细菌产生的丁酸', wrong: ['血液里的葡萄糖', '胃酸'], explain: '结肠内壁细胞的大部分能量来自发酵细菌产生的丁酸。' } },
  { id: 'CO-04', deck: 'colon', q: 'Most bacteria in the colon are what kind?', answer: 'Anaerobes that do not tolerate oxygen', wrong: ['Bacteria that need oxygen', 'Bacteria that use sunlight'], explain: 'Colon cells use up oxygen at the gut wall, keeping the colon almost oxygen-free.', refs: [38], zh: { q: '结肠里的大多数细菌是哪一类？', answer: '不耐氧的厌氧菌', wrong: ['需要氧气的细菌', '利用阳光的细菌'], explain: '结肠细胞在肠壁处耗尽氧气，让结肠几乎没有氧。' } },
  { id: 'CO-05', deck: 'colon', q: 'What keeps colon bacteria off the gut wall?', answer: 'A dense inner mucus layer', wrong: ['Stomach acid', 'A layer of fat'], explain: "The colon's inner mucus layer is nearly bacteria-free, while bacteria live in the looser outer layer.", refs: [39], zh: { q: '什么让结肠细菌远离肠壁？', answer: '一层致密的内层黏液', wrong: ['胃酸', '一层脂肪'], explain: '结肠的内层黏液几乎没有细菌，细菌住在较松散的外层。' } },
  { id: 'CO-06', deck: 'colon', q: 'Which two bacterial groups dominate most adult guts?', answer: 'Bacillota and Bacteroidota', wrong: ['Cyanobacteria and Spirochaetes', 'Proteobacteria and Chlamydiae'], explain: 'These phyla were renamed in 2021; many sources still call them Firmicutes and Bacteroidetes.', refs: [40, 41], zh: { q: '哪两类细菌在大多数成年人的肠道里占主导？', answer: '芽孢杆菌门（Bacillota）和拟杆菌门（Bacteroidota）', wrong: ['蓝细菌门和螺旋体门', '变形菌门和衣原体门'], explain: '这两个门在 2021 年改了名；许多资料仍用旧名厚壁菌门（Firmicutes）和拟杆菌门（Bacteroidetes）。' } },
  { id: 'CO-07', deck: 'colon', q: 'Which vitamin do gut bacteria help make?', answer: 'Vitamin K', wrong: ['Vitamin C', 'Vitamin D'], explain: 'Gut bacteria make forms of vitamin K2 and several B vitamins.', refs: [42], zh: { q: '肠道细菌帮助制造哪种维生素？', answer: '维生素 K', wrong: ['维生素 C', '维生素 D'], explain: '肠道细菌能制造几种形式的维生素 K2 和多种 B 族维生素。' } },
  { id: 'CO-08', deck: 'colon', q: 'What do colon bacteria turn some bile acids into?', answer: 'Secondary bile acids', wrong: ['Stomach acid', 'Sugar'], explain: 'Bacteria chemically modify bile acids that escape recycling, producing secondary bile acids.', refs: [23], zh: { q: '结肠细菌会把一部分胆汁酸变成什么？', answer: '次级胆汁酸', wrong: ['胃酸', '糖'], explain: '细菌对逃过循环利用的胆汁酸进行化学改造，产生次级胆汁酸。' } },
  { id: 'CO-09', deck: 'colon', q: 'What usually happens to gut bacteria during a course of antibiotics?', answer: 'Diversity drops, and recovery can be incomplete', wrong: ['All bacteria die permanently', 'Nothing changes'], explain: 'In a 2011 study, communities mostly recovered within weeks, but some species did not return.', refs: [43], zh: { q: '吃一个疗程的抗生素，肠道细菌通常会怎样？', answer: '多样性下降，恢复可能不完全', wrong: ['所有细菌永久死亡', '什么都没变'], explain: '在 2011 年的一项研究中，菌群大多在几周内恢复，但有些物种没有回来。' } },
  { id: 'CO-10', deck: 'colon', q: 'How quickly can a big diet change shift your gut microbiome?', answer: 'Within a day or two', wrong: ['Only after several years', 'Never'], explain: 'In a 2014 study, switching to an all-plant or all-animal diet changed the microbiome within days.', refs: [44], zh: { q: '饮食大幅改变后，肠道微生物组多快会变化？', answer: '一两天之内', wrong: ['要好几年之后', '永远不会变'], explain: '在 2014 年的一项研究中，改吃全素或全肉饮食后，微生物组几天内就变了。' } },
  // RE: level 7, the rectum
  { id: 'RE-01', deck: 'rectum', q: "What makes up a large share of stool's solid matter?", answer: 'Bacteria', wrong: ['Undigested meat', 'Dead stomach cells'], explain: "Bacteria account for roughly half of stool's dry mass, much more than leftover food.", refs: [45], zh: { q: '粪便的固体部分里，很大一部分是什么？', answer: '细菌', wrong: ['没消化的肉', '死掉的胃细胞'], explain: '细菌约占粪便干重的一半，远多于残留的食物。' } },
  { id: 'RE-02', deck: 'rectum', q: 'Which gases do gut microbes make that end up in farts?', answer: 'Hydrogen, carbon dioxide and methane', wrong: ['Oxygen and ozone', 'Helium and neon'], explain: 'Fermentation releases hydrogen and carbon dioxide; methane comes from archaea present in some people.', refs: [19], zh: { q: '肠道微生物产生的哪些气体最后成了屁？', answer: '氢气、二氧化碳和甲烷', wrong: ['氧气和臭氧', '氦气和氖气'], explain: '发酵释放氢气和二氧化碳；甲烷来自部分人肠道里的古菌。' } },
  { id: 'RE-03', deck: 'rectum', q: 'Does stool show exactly which microbes live on the gut wall?', answer: 'No, wall-attached communities differ', wrong: ['Yes, it matches exactly', 'Stool contains no microbes'], explain: "Stool mostly reflects microbes in the gut's contents; communities attached to the gut lining differ.", refs: [46], zh: { q: '粪便能准确显示哪些微生物住在肠壁上吗？', answer: '不能，附着在肠壁上的菌群不一样', wrong: ['能，完全一致', '粪便里没有微生物'], explain: '粪便主要反映肠道内容物里的微生物；附着在肠道内壁的菌群并不相同。' } },
  { id: 'RE-04', deck: 'rectum', q: 'What does the Bristol Stool Scale describe?', answer: 'Stool shape, a rough guide to how fast food moves through', wrong: ['Stool colour', 'How many bacteria are in stool'], explain: 'Its seven types run from hard lumps (slow transit) to liquid (fast transit).', refs: [47], zh: { q: '布里斯托大便分类法描述的是什么？', answer: '大便的性状，粗略反映食物通过的快慢', wrong: ['大便的颜色', '大便里有多少细菌'], explain: '它的七种类型从硬块（通过慢）到水样（通过快）。' } },
  { id: 'RE-05', deck: 'rectum', q: 'People with firmer stool (slower transit) tend to have gut microbiomes that are what?', answer: 'More species-rich', wrong: ['Less species-rich', 'Sterile'], explain: 'A 2016 study linked stool consistency strongly with microbial richness and composition.', refs: [48], zh: { q: '大便较硬（通过较慢）的人，肠道微生物组往往怎样？', answer: '物种更丰富', wrong: ['物种更少', '无菌'], explain: '2016 年的一项研究发现，大便的软硬程度与微生物的丰富度和组成密切相关。' } },
  { id: 'RE-06', deck: 'rectum', q: 'Does how a baby is born affect its first gut microbes?', answer: 'Yes; vaginal and caesarean births start babies with different microbes', wrong: ['No, all babies start the same', 'Babies are born with an adult microbiome'], explain: "Vaginally born babies first pick up microbes resembling their mother's vaginal community; caesarean-born babies, skin-like ones.", refs: [49], zh: { q: '出生方式会影响婴儿最初的肠道微生物吗？', answer: '会，顺产和剖宫产的婴儿起始微生物不同', wrong: ['不会，所有婴儿起点都一样', '婴儿生来就有成人的微生物组'], explain: '顺产婴儿最先获得的微生物像母亲的阴道菌群；剖宫产婴儿的则像皮肤菌群。' } },
  { id: 'RE-07', deck: 'rectum', q: 'Special sugars in breast milk mainly feed whom?', answer: 'Gut bacteria such as Bifidobacterium', wrong: ["The baby's own cells", 'Nobody; they are waste'], explain: 'Babies cannot digest human milk oligosaccharides, but certain gut bacteria can.', refs: [50], zh: { q: '母乳里的特殊糖类主要是给谁吃的？', answer: '双歧杆菌等肠道细菌', wrong: ['婴儿自己的细胞', '没人吃，它们是废物'], explain: '婴儿无法消化母乳低聚糖，但某些肠道细菌可以。' } },
  { id: 'RE-08', deck: 'rectum', q: "Around what age does a child's gut microbiome become adult-like?", answer: 'About 3 years', wrong: ['About 3 months', 'About 30 years'], explain: 'Gut communities change fast in infancy and settle into an adult-like state by about age three.', refs: [51], zh: { q: '孩子的肠道微生物组大约几岁变得像成人？', answer: '约 3 岁', wrong: ['约 3 个月', '约 30 岁'], explain: '肠道菌群在婴儿期变化很快，大约三岁时稳定成接近成人的状态。' } },
  { id: 'RE-09', deck: 'general', q: "How similar are two healthy people's gut microbiomes?", answer: "Quite different; each person's is unique", wrong: ['Identical', 'Identical within the same country'], explain: 'Healthy people differ widely in which species they carry, even when their microbes do similar jobs.', refs: [9], zh: { q: '两个健康人的肠道微生物组有多相似？', answer: '差别很大，每个人都独一无二', wrong: ['完全一样', '同一个国家的人完全一样'], explain: '健康的人携带的物种差别很大，即使他们的微生物做着相似的工作。' } },
  { id: 'RE-10', deck: 'rectum', q: "How long do most bacterial strains stay in an adult's gut?", answer: 'Years, often decades', wrong: ['A few days', 'A few weeks'], explain: 'A 2013 study found most strains stayed over five years and projected many would last decades.', refs: [52], zh: { q: '大多数细菌菌株在成年人肠道里能待多久？', answer: '好几年，常常几十年', wrong: ['几天', '几周'], explain: '2013 年的一项研究发现，大多数菌株在五年间一直都在，并推测许多会持续几十年。' } },
  // SQ: the challenge questions (plan 34), harder than level 7, any topic; drafted 17 Nov 2026 for Michael's
  // review (.claude/plans/Archive/34-super-cards-review.md), each on a reference the bank already cites.
  { id: 'SQ-01', deck: 'super', q: 'How does the colon keep its lining almost oxygen-free?', answer: 'Its cells burn butyrate, using up the oxygen', wrong: ['Bacteria pump the oxygen out', 'The mucus blocks every gas'], explain: 'Colon cells break down butyrate with oxygen, so little oxygen reaches the gut contents, which favours bacteria that cannot tolerate it.', refs: [38], zh: { q: '结肠是怎样让肠壁附近几乎没有氧气的？', answer: '肠壁细胞燃烧丁酸，把氧气用掉', wrong: ['细菌把氧气抽出去', '黏液挡住所有气体'], explain: '结肠细胞用氧气分解丁酸，所以很少有氧气进入肠道内容物，这有利于不耐氧的细菌。' } },
  { id: 'SQ-02', deck: 'super', q: "Who turns the liver's bile acids into secondary bile acids?", answer: 'A small group of colon bacteria', wrong: ['The liver itself', 'The gallbladder'], explain: 'Only a few colon bacteria, such as Clostridium scindens, can remove the chemical group that turns a primary bile acid into a secondary one.', refs: [23], zh: { q: '谁把肝脏分泌的胆汁酸变成次级胆汁酸？', answer: '少数几种结肠细菌', wrong: ['肝脏自己', '胆囊'], explain: '只有少数结肠细菌（例如 Clostridium scindens）能去掉那个化学基团，把初级胆汁酸变成次级胆汁酸。' } },
  { id: 'SQ-03', deck: 'super', q: 'What is a prophage?', answer: "A virus's DNA resting inside a bacterium's genome", wrong: ['A bacterium that eats viruses', 'An immune cell that hunts viruses'], explain: 'Temperate phages can insert their DNA into a bacterium and be copied with it at every division, until something triggers them to burst out.', refs: [20], zh: { q: '什么是原噬菌体？', answer: '潜伏在细菌基因组里的病毒 DNA', wrong: ['吃病毒的细菌', '追杀病毒的免疫细胞'], explain: '温和噬菌体能把自己的 DNA 插入细菌，跟着细菌每次分裂一起被复制，直到某个信号让它们破菌而出。' } },
  { id: 'SQ-04', deck: 'super', q: 'How do methane-making archaea help gut bacteria ferment?', answer: 'They use up the hydrogen bacteria make', wrong: ['They supply oxygen', 'They break down mucus'], explain: 'Hydrogen slows fermentation as it builds up. Methanobrevibacter smithii turns it into methane, so the bacteria keep fermenting.', refs: [19], zh: { q: '产甲烷的古菌怎样帮助肠道细菌发酵？', answer: '它们把细菌产生的氢气用掉', wrong: ['它们提供氧气', '它们分解黏液'], explain: '氢气积累会让发酵变慢。史氏甲烷短杆菌把氢气变成甲烷，细菌就能继续发酵。' } },
  { id: 'SQ-05', deck: 'super', q: "About how much IgA antibody does an adult's gut release each day?", answer: 'A few grams', wrong: ['A few micrograms', 'A few kilograms'], explain: 'The gut lining makes more IgA than all other antibodies combined, about three grams a day, coating microbes in the gut.', refs: [26], zh: { q: '成年人的肠道每天大约分泌多少 IgA 抗体？', answer: '几克', wrong: ['几微克', '几千克'], explain: '肠壁产生的 IgA 比其他所有抗体加起来还多，每天约三克，用来包裹肠道里的微生物。' } },
  { id: 'SQ-06', deck: 'super', q: 'Where does most of the propionate made by gut bacteria go?', answer: 'To the liver', wrong: ['To the brain', 'To the lungs'], explain: 'Colon cells use most butyrate, the liver takes up most propionate, and acetate travels on in the blood to the rest of the body.', refs: [30], zh: { q: '肠道细菌产生的丙酸大多去了哪里？', answer: '肝脏', wrong: ['大脑', '肺'], explain: '丁酸大多被结肠细胞用掉，丙酸大多被肝脏吸收，乙酸则随血液流到全身。' } },
  { id: 'SQ-07', deck: 'super', q: "Which molecule builds the colon's two mucus layers?", answer: 'MUC2 mucin', wrong: ['Keratin', 'Collagen'], explain: 'Goblet cells release MUC2, which forms a dense inner layer that bacteria cannot enter and a loose outer layer where they live.', refs: [17], zh: { q: '结肠的两层黏液是由哪种分子构成的？', answer: 'MUC2 黏蛋白', wrong: ['角蛋白', '胶原蛋白'], explain: '杯状细胞分泌 MUC2，形成细菌进不去的致密内层，以及细菌居住的疏松外层。' } },
  { id: 'SQ-08', deck: 'super', q: 'Most gut bacteria that use vitamin B12 get it how?', answer: 'From the few species that can make it', wrong: ['They all make their own', 'From stomach acid'], explain: 'Many gut bacteria have enzymes that need B12, but only a minority can make it, so it is shared, and competed for, across the community.', refs: [28], zh: { q: '大多数需要维生素 B12 的肠道细菌是怎样得到它的？', answer: '从少数能制造它的菌种那里', wrong: ['它们都自己制造', '从胃酸里'], explain: '许多肠道细菌的酶需要 B12，但只有少数能制造它，所以整个群落都在分享和争夺它。' } },
  { id: 'SQ-09', deck: 'super', q: 'In a 2014 study, an all-animal diet boosted which gut bacteria?', answer: 'Bile-tolerant ones such as Bilophila', wrong: ['Fibre fermenters such as Roseburia', 'Soil bacteria that need oxygen'], explain: 'Within days, a meat-and-cheese diet raised bile-tolerant microbes such as Bilophila and lowered bacteria that ferment plant fibre.', refs: [44], zh: { q: '2014 年的一项研究中，全动物性饮食让哪类肠道细菌增多？', answer: '耐胆汁的细菌，如 Bilophila', wrong: ['发酵膳食纤维的细菌，如 Roseburia', '需要氧气的土壤细菌'], explain: '几天之内，以肉和奶酪为主的饮食就让 Bilophila 等耐胆汁微生物增多，让发酵植物纤维的细菌减少。' } },
  { id: 'SQ-10', deck: 'super', q: 'Compared with US adults, adults in rural Malawi and Venezuela had gut microbiomes that were what?', answer: 'More diverse', wrong: ['Less diverse', 'Identical'], explain: 'A 2012 study of three countries found that US adults had the least diverse gut communities.', refs: [51], zh: { q: '与美国成年人相比，马拉维农村和委内瑞拉的成年人的肠道微生物组怎样？', answer: '更多样', wrong: ['更单一', '完全一样'], explain: '2012 年一项比较三个国家的研究发现，美国成年人的肠道菌群多样性最低。' } },
  { id: 'SQ-11', deck: 'super', q: "Which cells over Peyer's patches grab gut microbes for the immune system?", answer: 'M cells', wrong: ['Red blood cells', 'Goblet cells'], explain: "M cells carry microbes and particles across the gut lining to immune cells waiting underneath in the Peyer's patch.", refs: [25], zh: { q: '派尔集合淋巴结上方的哪种细胞会从肠道抓取微生物，交给免疫系统？', answer: 'M 细胞', wrong: ['红细胞', '杯状细胞'], explain: 'M 细胞把微生物和颗粒运过肠壁，交给在派尔集合淋巴结里等着的免疫细胞。' } },
  { id: 'SQ-12', deck: 'super', q: 'In the Human Microbiome Project, what varied less between healthy people?', answer: "The microbes' metabolic pathways", wrong: ['The species present', 'Neither varied'], explain: 'People carried very different species, but the jobs those microbes could do, their metabolic pathways, stayed much the same.', refs: [9], zh: { q: '在人类微生物组计划中，健康人之间哪一方面差异较小？', answer: '微生物的代谢途径', wrong: ['存在的物种', '两者都没有差异'], explain: '每个人携带的物种差别很大，但这些微生物能做的工作，也就是代谢途径，却大致相同。' } },
  { id: 'SQ-13', deck: 'super', q: 'Unlike rabbits, where do cows ferment plants?', answer: 'In the rumen, before the true stomach', wrong: ['In the caecum, after the small intestine', 'In the mouth, while chewing'], explain: 'Cows are foregut fermenters: microbes in the rumen break down plants before food reaches the acid stomach and small intestine.', refs: [32], zh: { q: '和兔子不同，牛在哪里发酵植物？', answer: '在瘤胃里，位于真胃之前', wrong: ['在盲肠里，位于小肠之后', '在嘴里，一边嚼一边发酵'], explain: '牛是前肠发酵动物：食物到达酸性的胃和小肠之前，瘤胃里的微生物就先把植物分解了。' } },
  { id: 'SQ-14', deck: 'super', q: 'Mice raised with no microbes at all have what kind of gut immune system?', answer: 'Underdeveloped', wrong: ['Overactive and larger', 'Exactly normal'], explain: 'Germ-free mice grow up with an underdeveloped gut immune system; gut microbes help it mature.', refs: [27], zh: { q: '在完全没有微生物的环境里长大的小鼠，肠道免疫系统是什么样的？', answer: '发育不全', wrong: ['过度活跃而且更大', '完全正常'], explain: '无菌小鼠的肠道免疫系统发育不全；肠道微生物帮助免疫系统成熟。' } },
  { id: 'SQ-15', deck: 'super', q: 'How does H. pylori reach the safer zone by the stomach wall?', answer: 'It swims through the mucus with its flagella', wrong: ['It rides in on stomach acid', 'Red blood cells carry it there'], explain: 'Its spiral shape and whip-like flagella let H. pylori drill through thick mucus to the less acidic layer by the stomach lining.', refs: [4], zh: { q: '幽门螺杆菌怎样到达胃壁旁比较安全的地方？', answer: '用鞭毛在黏液里游过去', wrong: ['搭着胃酸进去', '由红细胞带过去'], explain: '幽门螺杆菌的螺旋形身体和鞭子一样的鞭毛，让它能钻过厚厚的黏液，到达胃壁旁酸性较弱的一层。' } },
  { id: 'SQ-16', deck: 'super', q: 'People took two courses of the same antibiotic. How did their gut communities respond?', answer: 'Differently in each person, and not fully back', wrong: ['The same in everyone, then fully back', 'Not at all'], explain: 'After each course of ciprofloxacin, communities shifted within days; how they shifted varied by person, and after the second course they did not fully return.', refs: [43], zh: { q: '人们服用了两个疗程的同一种抗生素，他们的肠道菌群有什么反应？', answer: '每个人都不一样，而且没有完全恢复', wrong: ['每个人都一样，之后完全恢复', '完全没有变化'], explain: '每个疗程的环丙沙星都让菌群在几天内改变；变化因人而异，第二个疗程后也没有完全恢复。' } },
  { id: 'SQ-17', deck: 'super', q: "Why were DNA surveys needed to map the gut's microbes?", answer: 'Many gut microbes are hard to grow in a lab', wrong: ['Microscopes cannot see bacteria', 'Gut microbes die in daylight'], explain: 'Many gut microbes refuse to grow on lab dishes, so reading their DNA, such as their 16S rRNA genes, revealed species no one had grown.', refs: [7], zh: { q: '为什么需要用 DNA 调查来摸清肠道里的微生物？', answer: '许多肠道微生物很难在实验室里培养', wrong: ['显微镜看不到细菌', '肠道微生物见光就死'], explain: '许多肠道微生物在培养皿上长不出来，所以要读取它们的 DNA（例如 16S rRNA 基因），才能发现从没被培养过的物种。' } },
  { id: 'SQ-18', deck: 'super', q: 'A 2019 study tracked strains along the gut. What did it find about mouth bacteria?', answer: 'Many travel down and settle in the gut', wrong: ['None survive past the stomach', "Only babies' reach the gut"], explain: 'Matching strains in saliva and stool showed that oral bacteria often pass the stomach and settle in the gut of healthy adults.', refs: [6], zh: { q: '2019 年一项研究追踪了消化道里的菌株，关于口腔细菌发现了什么？', answer: '许多会往下走，并在肠道里定居', wrong: ['没有一种能活过胃', '只有婴儿的能到达肠道'], explain: '比对唾液和粪便里的菌株发现，健康成年人的口腔细菌常常穿过胃，在肠道里住下来。' } },
  { id: 'SQ-19', deck: 'super', q: 'Compared with when they were babies, most adults worldwide make how much lactase?', answer: 'Much less', wrong: ['Much more', 'The same'], explain: 'About two in three adults worldwide lose most of their lactase after weaning; groups with a long history of dairy farming more often keep it.', refs: [16], zh: { q: '和婴儿时期相比，世界上大多数成年人产生的乳糖酶有多少？', answer: '少得多', wrong: ['多得多', '一样多'], explain: '全世界约三分之二的成年人在断奶后失去大部分乳糖酶；有长期养奶牛历史的人群更常保留它。' } },
  { id: 'SQ-20', deck: 'super', q: "About how many bacterial species does one person's gut hold, by a 2010 estimate?", answer: 'At least 160', wrong: ['About 16', 'About 16,000'], explain: 'Sequencing stool from 124 Europeans found each person carried at least 160 bacterial species, out of about 1,000 common across everyone.', refs: [18], zh: { q: '根据 2010 年的估计，一个人的肠道里大约有多少种细菌？', answer: '至少 160 种', wrong: ['大约 16 种', '大约 1.6 万种'], explain: '对 124 名欧洲人的粪便测序发现，每人至少有 160 种细菌，而所有人共有的常见细菌约有 1000 种。' } },
  { id: 'SQ-21', deck: 'super', q: 'Which of these is a classic prebiotic?', answer: 'Inulin, a fibre in chicory root', wrong: ['Vitamin C', 'Table salt'], explain: 'Inulin-type fibres and galacto-oligosaccharides are well-established prebiotics: we cannot digest them, but some gut bacteria use them selectively.', refs: [34], zh: { q: '下面哪一种是经典的益生元？', answer: '菊粉，一种存在于菊苣根里的膳食纤维', wrong: ['维生素 C', '食盐'], explain: '菊粉类纤维和低聚半乳糖是公认的益生元：我们无法消化它们，但某些肠道细菌会有选择地利用它们。' } },
];

